begin;
create table if not exists public.observations (id uuid primary key default gen_random_uuid(),reference_no text not null unique,submitted_at timestamptz not null default now(),observation_datetime timestamptz not null default now(),submitter_name text,submitter_email text,phone text,company text,observation_type text,location text,observation text,action_taken text,photo_url text,is_anonymous boolean not null default false,deleted boolean not null default false,deleted_at timestamptz,deleted_by uuid references public.admins(id) on delete set null,delete_reason text);
alter table public.observations add column if not exists submitted_at timestamptz not null default now(); alter table public.observations add column if not exists observation_datetime timestamptz not null default now(); alter table public.observations add column if not exists submitter_name text; alter table public.observations add column if not exists submitter_email text; alter table public.observations add column if not exists phone text; alter table public.observations add column if not exists company text; alter table public.observations add column if not exists observation_type text; alter table public.observations add column if not exists location text; alter table public.observations add column if not exists observation text; alter table public.observations add column if not exists action_taken text; alter table public.observations add column if not exists photo_url text; alter table public.observations add column if not exists is_anonymous boolean not null default false; alter table public.observations add column if not exists deleted boolean not null default false; alter table public.observations add column if not exists deleted_at timestamptz; alter table public.observations add column if not exists deleted_by uuid references public.admins(id) on delete set null; alter table public.observations add column if not exists delete_reason text;
create index if not exists idx_observations_month on public.observations(observation_datetime desc); create index if not exists idx_observations_deleted on public.observations(deleted);
create table if not exists public.admin_audit_log (id bigint generated by default as identity primary key,created_at timestamptz not null default now(),admin_id uuid references public.admins(id) on delete set null,admin_email text,reference_no text,action text not null,from_status text,to_status text,details text);
create index if not exists idx_admin_audit_created on public.admin_audit_log(created_at desc);
create table if not exists public.recognition (id bigint generated by default as identity primary key,month_key text not null check (month_key ~ '^\d{4}-\d{2}$'),reference_no text not null,category text not null,notes text,selected_by uuid references public.admins(id) on delete set null,selected_by_email text,created_at timestamptz not null default now());
create index if not exists idx_recognition_month on public.recognition(month_key); create index if not exists idx_recognition_reference on public.recognition(reference_no);
alter table public.observations enable row level security; alter table public.admin_audit_log enable row level security; alter table public.recognition enable row level security;
grant select,insert,update,delete on public.observations to service_role; grant select,insert,update,delete on public.admin_audit_log to service_role; grant select,insert,update,delete on public.recognition to service_role; grant usage,select on all sequences in schema public to service_role;
commit;
